using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1QualityExport {
 public static object Run(){if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/F1_FullFloor/",cache=Path.GetFullPath(Path.Combine(Application.dataPath,"../Temp/F1MeshClean/"));Directory.CreateDirectory(cache);var plan=JObject.Parse(File.ReadAllText(h+"quality_export_plan.json"));var assets=plan["patches"].Select(p=>(string)plan["rows"][(int)p["renderer"]]["asset"]).Distinct().ToArray();var result=new System.Collections.Generic.List<object>();foreach(string asset in assets){if(!asset.Contains("/1F/F1_"))throw new Exception("Protected asset "+asset);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(asset);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(mesh,out string guid,out long local);string key=guid+"_"+local;var vs=mesh.vertices;var ns=mesh.normals;var uv=mesh.uv;var uv2=mesh.uv2;bool two=uv2.Length==vs.Length;using(var w=new BinaryWriter(File.Create(cache+key+".bin"))){w.Write(vs.Length);w.Write(mesh.subMeshCount);w.Write(two?1:0);for(int i=0;i<vs.Length;i++){w.Write(vs[i].x);w.Write(vs[i].y);w.Write(vs[i].z);var n=ns.Length==vs.Length?ns[i]:Vector3.up;w.Write(n.x);w.Write(n.y);w.Write(n.z);var u=uv.Length==vs.Length?uv[i]:Vector2.zero;w.Write(u.x);w.Write(u.y);if(two){w.Write(uv2[i].x);w.Write(uv2[i].y);}}for(int si=0;si<mesh.subMeshCount;si++){var ix=mesh.GetIndices(si);w.Write(ix.Length);foreach(int i in ix)w.Write(i);}}result.Add(new{asset,key,name=mesh.name,materials=f.GetComponent<Renderer>().sharedMaterials.Select(m=>m.name).ToArray()});}}
 File.WriteAllText(h+"clean_source.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{assets=assets.Length,meshes=result.Count};}
}
